export interface Baseline {
  id: string;
  benchmark_version: string;
  kind:
    | "human-crowd-average"
    | "human-crowd-best"
    | "human-expert-average"
    | "human-expert-best"
    | "theoretical-maximum"
    | "measured-ceiling"
    | "experimental-replicate"
    | "operational-system"
    | "noise-ceiling"
    | "classical-algorithm"
    | "random-chance"
    | "field-practice-reference";
  metric: string;
  value?: number | null;
  value_absent_reason?: ("no-published-comparator" | "not-applicable" | "not-yet-measured") | null;
  n_humans?: number | null;
  population?: string | null;
  time_limit?: string | null;
  is_primary?: boolean;
  source?: string | null;
  notes?: string | null;
}
export interface Lineage {
  role?: ("root" | "variant" | "fork") | null;
  supersedes?: string[];
  superseded_by?: string[];
  subset_of?: string | null;
  extended_by?: string[];
  decontaminates?: string | null;
  correlates_with?: Correlation[];
  variants?: Variant[];
  forks?: Fork[];
  views?: View[];
  [k: string]: unknown;
}
export interface Correlation {
  benchmark: string;
  coefficient?: number | null;
  source?: string | null;
}
/**
 * A same-maintainer variant (subset, filtered subset, extension).
 */
export interface Variant {
  id: string;
  relation: string;
  n_items?: number | null;
  n_items_history?: Count[];
  co_maintainer?: string | null;
  source: string;
  quote?: string | null;
  [k: string]: unknown;
}
/**
 * A derivative by another maintainer.
 */
export interface Fork {
  id: string;
  maintainer: string;
  source: string;
  quote?: string | null;
}
/**
 * A board that is only a filter on another, not a benchmark of its own.
 */
export interface View {
  name: string;
  of: string;
  source: string;
  quote?: string | null;
}
export interface Curation {
  added_by: string;
  added_on: string;
  last_verified: string;
  verification_status?:
    | "ai-drafted-unverified"
    | "machine-ingested"
    | "curator-reviewed"
    | "primary-source-verified"
    | "expert-reviewed"
    | "maintainer-confirmed";
  /**
   * @minItems 1
   */
  sources: [string | InlineSource, ...(string | InlineSource)[]];
  confidence?: "low" | "medium" | "high";
  notes?: string | null;
  not_yet_available?: NotYetAvailable[];
  unreachable?: Unreachable[];
  personal_data_excluded?: PersonalDataExcluded[];
  [k: string]: unknown;
}
/**
 * A source described inline (the Phase-0 entries' shape). A Source lives in data/sources/ and is
 * referenced by id; the inline description is deferred to it (group `curation_sources_inline`).
 */
export interface InlineSource {
  id: string;
  [k: string]: unknown;
}
export interface NotYetAvailable {
  what: string;
  expected: string;
  consequence: string;
}
export interface Unreachable {
  url: string;
  http_status: number;
  consequence: string;
}
export interface PersonalDataExcluded {
  source: string;
  what: string;
}
